// @ts-nocheck
"use client";

import React, { useRef, useMemo } from "react";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { OrbitControls, Line } from "@react-three/drei";
import * as THREE from "three";

interface Node {
  id: string;
  lat: number;
  lng: number;
}

interface Route {
  from: string;
  to: string;
  highlighted?: boolean;
}

const NODES: Node[] = [
  { id: "SHA", lat: 31.23, lng: 121.47 },
  { id: "SIN", lat: 1.35, lng: 103.82 },
  { id: "SUEZ", lat: 29.97, lng: 32.55 },
  { id: "RTM", lat: 51.92, lng: 4.47 },
  { id: "FRA", lat: 50.11, lng: 8.68 },
  { id: "DXB", lat: 25.2, lng: 55.27 },
];

const ROUTES: Route[] = [
  { from: "SHA", to: "SIN", highlighted: true },
  { from: "SIN", to: "SUEZ" },
  { from: "SUEZ", to: "RTM" },
  { from: "RTM", to: "FRA", highlighted: true },
  { from: "DXB", to: "FRA" },
];

function latLngToVec3(lat: number, lng: number, r: number): THREE.Vector3 {
  const phi = (90 - lat) * (Math.PI / 180);
  const theta = (lng + 180) * (Math.PI / 180);
  return new THREE.Vector3(
    -(r * Math.sin(phi) * Math.cos(theta)),
    r * Math.cos(phi),
    r * Math.sin(phi) * Math.sin(theta)
  );
}

function Lane({ p1, p2, highlighted }: { p1: THREE.Vector3; p2: THREE.Vector3; highlighted?: boolean }) {
  const dotRef = useRef<THREE.Mesh>(null);
  const prog = useRef(Math.random());

  const { curve, pts } = useMemo(() => {
    const mid = new THREE.Vector3().addVectors(p1, p2).multiplyScalar(0.5);
    mid.normalize().multiplyScalar(2.5 + p1.distanceTo(p2) * 0.22);
    const c = new THREE.QuadraticBezierCurve3(p1, mid, p2);
    return { curve: c, pts: c.getPoints(48) };
  }, [p1, p2]);

  useFrame((_, delta) => {
    if (dotRef.current && highlighted) {
      prog.current = (prog.current + delta * 0.15) % 1;
      dotRef.current.position.copy(curve.getPoint(prog.current));
    }
  });

  return (
    <group>
      <Line
        points={pts}
        color={highlighted ? "#C79A4B" : "#2A3040"}
        lineWidth={highlighted ? 1.4 : 1}
        transparent
        opacity={highlighted ? 0.85 : 0.4}
      />
      {highlighted && (
        <mesh ref={dotRef}>
          <sphereGeometry args={[0.03, 10, 10]} />
          <meshBasicMaterial color="#EBC57A" />
        </mesh>
      )}
    </group>
  );
}

function Globe() {
  const ref = useRef<THREE.Group>(null);
  const radius = 2.3;

  useFrame((_, delta) => {
    if (ref.current) ref.current.rotation.y += delta * 0.035;
  });

  const nodeMap = useMemo(() => {
    const m = new Map<string, THREE.Vector3>();
    NODES.forEach((n) => m.set(n.id, latLngToVec3(n.lat, n.lng, radius)));
    return m;
  }, []);

  return (
    <group ref={ref}>
      <mesh>
        <sphereGeometry args={[radius, 28, 20]} />
        <meshBasicMaterial color="#232936" wireframe transparent opacity={0.35} />
      </mesh>
      <mesh>
        <sphereGeometry args={[radius * 0.995, 64, 64]} />
        <meshBasicMaterial color="#0E1117" transparent opacity={0.9} />
      </mesh>

      {ROUTES.map((r, i) => {
        const p1 = nodeMap.get(r.from);
        const p2 = nodeMap.get(r.to);
        if (!p1 || !p2) return null;
        return <Lane key={i} p1={p1} p2={p2} highlighted={r.highlighted} />;
      })}

      {NODES.map((n) => {
        const pos = nodeMap.get(n.id);
        if (!pos) return null;
        return (
          <mesh key={n.id} position={pos}>
            <sphereGeometry args={[0.032, 12, 12]} />
            <meshBasicMaterial color="#5B6472" />
          </mesh>
        );
      })}
    </group>
  );
}

function IntroCamera() {
  const { camera } = useThree();
  const started = useRef(0);
  const from = useRef(new THREE.Vector3(0, 3.4, 8.5));
  const to = useRef(new THREE.Vector3(0.6, 0.4, 5.6));

  useFrame((state) => {
    if (started.current === 0) started.current = state.clock.elapsedTime;
    const t = state.clock.elapsedTime - started.current;
    const duration = 2.4;
    if (t < duration) {
      const p = 1 - Math.pow(1 - t / duration, 3);
      camera.position.lerpVectors(from.current, to.current, p);
      camera.lookAt(0, 0, 0);
    }
  });

  return null;
}

export default function ManifestGlobe() {
  return (
    <div className="w-full h-full">
      <Canvas camera={{ position: [0, 3.4, 8.5], fov: 40 }}>
        <ambientLight intensity={0.5} />
        <pointLight position={[10, 10, 10]} intensity={0.6} color="#8B93A3" />
        <IntroCamera />
        <Globe />
        <OrbitControls
          enablePan={false}
          enableZoom={false}
          minDistance={5}
          maxDistance={7}
          autoRotate={false}
          rotateSpeed={0.35}
        />
      </Canvas>
    </div>
  );
}